public static bool TryGetInitials(string? fullName, out string initials)
{
    initials = "";

    if (string.IsNullOrWhiteSpace(fullName))
        return false;

    var parts = fullName.Split(' ', StringSplitOptions.RemoveEmptyEntries);

    var sb = new System.Text.StringBuilder();
    foreach (var part in parts)
        sb.Append(char.ToUpperInvariant(part[0]));

    initials = sb.ToString();
    return true;
}

// Points to notice:
//  - initials is assigned FIRST, so every return path has it set.
//    An out parameter must be assigned before the method returns.
//  - IsNullOrWhiteSpace covers null, "" and "   " in one call.
//  - RemoveEmptyEntries handles double spaces without extra code.

