public class Account
{
    public string Number { get; }
    public decimal Balance { get; private set; }

    public Account(string number, decimal opening = 0m)
    {
        if (string.IsNullOrWhiteSpace(number))
            throw new ArgumentException("Account number is required.", nameof(number));
        if (opening < 0)
            throw new ArgumentOutOfRangeException(nameof(opening), "Opening balance cannot be negative.");

        Number = number.Trim();
        Balance = opening;
    }

    public void Deposit(decimal amount)
    {
        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Deposit must be positive.");
        Balance += amount;
    }

    public void Withdraw(decimal amount)
    {
        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Withdrawal must be positive.");
        if (amount > Balance)
            throw new InvalidOperationException($"Insufficient funds: balance {Balance}, requested {amount}.");
        Balance -= amount;
    }

    public override string ToString() => $"Account {Number}: {Balance:N2}";
}

// The key moves:
//  - Number is { get; } so it is fixed after construction.
//  - Balance is { get; private set; } so it is readable everywhere but
//    only the class itself can change it.
//  - Validation lives in the constructor, so no code path produces an
//    invalid Account. This is the difference between a type that can be
//    misused and one that cannot.
//  - nameof(amount) keeps the parameter name correct if it is ever renamed.

