// Both — and the reason is that the two requirements are different in kind.

// The interface is the contract the rest of the application depends on.
// It gives substitutability and testability: callers depend on this, not on
// any concrete channel, and a test can supply a fake.
public interface INotifier
{
    Task SendAsync(string recipient, string message);
    string Channel { get; }
}

// The abstract class carries the SHARED IMPLEMENTATION the three channels
// genuinely have in common. It exists only because there is real code to
// share — not to express the shape.
public abstract class NotifierBase : INotifier
{
    public abstract string Channel { get; }
    protected abstract Task DeliverAsync(string recipient, string message);

    public DateTime? LastSentUtc { get; private set; }

    public async Task SendAsync(string recipient, string message)
    {
        if (string.IsNullOrWhiteSpace(recipient))
            throw new ArgumentException("Recipient is required.", nameof(recipient));

        await DeliverAsync(recipient, message);   // the one varying step
        LastSentUtc = DateTime.UtcNow;
    }
}

public class EmailNotifier : NotifierBase
{
    public override string Channel => "Email";
    protected override Task DeliverAsync(string to, string msg) => Task.CompletedTask;
}

// Why not each alternative:
//
// Interface alone: the validation and timestamp logic would be copy-pasted
//   into all three channels, and would drift apart over time.
//
// Abstract class alone: callers would depend on a concrete base type, so a
//   test would have to subclass it rather than supply a simple fake, and any
//   future notifier that cannot reuse the base is locked out.
//
// Both: callers depend on the interface; implementations opt into the shared
//   code. Note the template-method shape — SendAsync is sealed logic that
//   calls the abstract DeliverAsync, so the invariant (validate, send, record)
//   cannot be skipped by a subclass.

