6.solution:
// Why it is slow:
// List.Contains performs a linear scan - O(n). Called once per incoming item,
// that is O(n*m). With 50,000 incoming and 50,000 processed it is up to
// 2.5 billion comparisons.

public static List<string> FindDuplicates(
    IEnumerable<string> incoming, IEnumerable<string> alreadyProcessed)
{
    var seen = new HashSet<string>(alreadyProcessed, StringComparer.Ordinal);

    return incoming.Where(seen.Contains).ToList();
}

// HashSet.Contains is O(1), so the whole method becomes O(n + m) - about
// 100,000 operations instead of 2.5 billion.
//
// Two refinements worth noting:
//  - Parameters widened to IEnumerable<string> so callers can pass anything.
//  - An explicit StringComparer. The default is fine here, but being explicit
//    about ordinal vs culture-sensitive comparison avoids surprises when the
//    same code runs under a different locale.

