7.solution:
// Problems:
// 1. The connection is never disposed - no using. Under load this exhausts
//    the connection pool and the symptom is an unrelated-looking timeout.
// 2. SQL injection. The account number is concatenated into the SQL text.
// 3. The exception is swallowed and converted into a balance of 0 - a wrong
//    answer that looks like a real one. This is the worst problem here.
// 4. catch (Exception) catches everything, including bugs that should surface.
// 5. A missing account is indistinguishable from an error, since both return 0.
//    ExecuteScalar returns null for no rows and the cast would throw anyway.

public decimal? GetBalance(string accountNumber)
{
    if (string.IsNullOrWhiteSpace(accountNumber))
        throw new ArgumentException("Account number is required.", nameof(accountNumber));

    using var conn = new SqlConnection(_connectionString);
    using var cmd  = new SqlCommand(
        "SELECT balance FROM accounts WHERE number = @number", conn);

    cmd.Parameters.AddWithValue("@number", accountNumber);

    conn.Open();
    var result = cmd.ExecuteScalar();

    return result is null or DBNull ? null : (decimal)result;
}

// What changed and why:
//  - using on both connection and command: deterministic cleanup even on throw.
//  - A parameterised query: the value can never be interpreted as SQL.
//  - No catch at all. This method cannot meaningfully recover from a database
//    failure, so it lets the exception propagate to a layer that can decide.
//    That is 'throw low, catch high'.
//  - decimal? so 'no such account' is representable, and distinct from both
//    zero balance and failure.

