public class InterestCalculator
{
    private readonly Func<DateTime> _now;
    private readonly Func<decimal, decimal> _annualRate;

    // Production: new InterestCalculator()
    // Test:       new InterestCalculator(() => new DateTime(2026,1,1), _ => 0.05m)
    public InterestCalculator(
        Func<DateTime>? now = null,
        Func<decimal, decimal>? annualRate = null)
    {
        _now = now ?? (() => DateTime.UtcNow);
        _annualRate = annualRate ?? (_ => 0.05m);
    }

    public decimal AccruedInterest(decimal principal, DateTime openedOn)
    {
        if (principal < 0)
            throw new ArgumentOutOfRangeException(nameof(principal));

        var days = (_now() - openedOn).Days;
        if (days <= 0) return 0m;

        return principal * _annualRate(principal) * days / 365m;
    }
}

// Why this shape:
//  - Func<DateTime> for the clock: the single most useful delegate injection
//    there is, because time is the most common reason a class is untestable.
//  - Func<decimal, decimal> rather than a plain decimal for the rate, so the
//    rate can depend on the balance - tiered rates come free.
//  - Optional parameters with sensible defaults mean production code does not
//    have to know this flexibility exists, while tests can use it.
//  - An interface would also work, but for one or two values a delegate is
//    less machinery for the same benefit.

