13.solution:
// Problems:
// 1. Loads EVERY account including inactive ones, then filters in memory.
//    The Status filter should run in SQL.
// 2. N+1 (really N+2): a.Transactions is lazy-loaded per account, and twice
//    per account at that - once for Count and once for Sum.
// 3. Full entity tracking for a read-only query, plus every column of every
//    account loaded when only two are needed.

public async Task<List<AccountSummary>> GetSummariesAsync(CancellationToken ct)
{
    return await _db.Accounts
        .AsNoTracking()                                   // read-only
        .Where(a => a.Status == AccountStatus.Active)     // filtered in SQL
        .Select(a => new AccountSummary                   // projection: 4 columns
        {
            Number = a.Number,
            Owner  = a.Owner,
            Count  = a.Transactions.Count(),              // aggregated in SQL
            Total  = a.Transactions.Sum(t => (decimal?)t.Amount) ?? 0m
        })
        .ToListAsync(ct);
}

// One query. The database does the filtering and the aggregation, and only
// the four values per row cross the network.
