14.solution:
// Problems:
// 1. Passwords stored and compared in PLAINTEXT. A database leak is an
//    immediate total compromise, and the comparison is also not
//    constant-time. Store a slow salted hash instead.
// 2. The error messages distinguish 'no such user' from 'wrong password',
//    which turns the endpoint into a username enumerator. Also both should
//    be 401, not 400 - this is an authentication failure, not a malformed
//    request.
// 3. The password and account number are put into the JWT. A JWT is signed,
//    not encrypted, so both are readable by anyone holding the token.
// 4. A 30-day expiry. JWTs cannot be revoked, so a stolen token is valid
//    for a month. Minutes, plus a revocable refresh token.

[HttpPost("login")]
[AllowAnonymous]
[EnableRateLimiting("login")]          // attempts must be bounded
public async Task<IActionResult> Login(LoginRequest req, CancellationToken ct)
{
    var user = await _db.Users
        .FirstOrDefaultAsync(u => u.Username == req.Username, ct);

    // One message, one status code, for every failure mode.
    const string failure = "Invalid username or password.";

    if (user is null)
        return Unauthorized(failure);

    var check = _hasher.VerifyHashedPassword(
        user, user.PasswordHash, req.Password);

    if (check == PasswordVerificationResult.Failed)
    {
        _logger.LogWarning("Failed login for {Username}", req.Username);
        return Unauthorized(failure);
    }

    // Only what authorisation actually needs. No PII, no secrets.
    var claims = new List<Claim>
    {
        new(JwtRegisteredClaimNames.Sub, user.Id.ToString()),
        new(ClaimTypes.Name, user.Username),
        new(ClaimTypes.Role, user.Role)
    };

    var token = new JwtSecurityToken(
        issuer:   _jwt.Issuer,
        audience: _jwt.Audience,
        claims:   claims,
        expires:  DateTime.UtcNow.AddMinutes(15),
        signingCredentials: creds);

    return Ok(new
    {
        accessToken  = new JwtSecurityTokenHandler().WriteToken(token),
        refreshToken = await _refreshTokens.IssueAsync(user.Id, ct),
        expiresIn    = 900
    });
}

// Note the account number is gone from the token entirely. If an endpoint
// needs it, look it up from the 'sub' claim server-side. The rule is that a
// token carries identity and authorisation facts, never data.

