15.solution:
// Problems:
// 1. Console.WriteLine instead of ILogger - no level, no context, no sink.
// 2. Serialising the whole request, which includes the full card number.
//    This is the serious one: PII and card data now live in the log file.
// 3. LogError used for routine progress. If everything is an error, alerts
//    become meaningless.
// 4. String interpolation and concatenation, so nothing is queryable and the
//    string is built even when the level is off.
// 5. The failure is logged at Information, so a real error is invisible to
//    anyone filtering for problems.
// 6. 'throw ex' resets the stack trace to this line, and the error is both
//    logged AND rethrown - so it will be logged again higher up.
// Also: no correlation, and no duration on the external call.

public async Task<bool> TransferAsync(
    TransferRequest request, CancellationToken ct)
{
    using var scope = _logger.BeginScope(
        "Transfer {Reference}", request.Reference);

    _logger.LogInformation(
        "Transfer initiated for {Account} amount {Amount}",
        Mask(request.AccountNumber), request.Amount);

    var sw = Stopwatch.StartNew();
    try
    {
        var result = await _core.SendAsync(request, ct);

        _logger.LogInformation(
            "Transfer completed with {Result} in {ElapsedMs}ms",
            result, sw.ElapsedMilliseconds);

        return result;
    }
    catch (HttpRequestException ex)
    {
        // Logged here because we are adding context the caller lacks,
        // then rethrown with the original stack intact.
        _logger.LogError(ex,
            "Core banking call failed after {ElapsedMs}ms",
            sw.ElapsedMilliseconds);
        throw;
    }
}

private static string Mask(string account) =>
    account.Length <= 4 ? "****" : new string('*', account.Length - 4)
                                   + account[^4..];

// Note: the card number is never logged at all, at any level. The account
// number is masked to its last four digits. The scope means every line
// inside carries the reference without repeating it, and the duration is
// recorded on both the success and the failure path.

