        ?? throw new AccountNotFoundException(to);

    if (source.Balance < amount)
        throw new InsufficientFundsException(from, amount, source.Balance);

    await _accounts.DebitAsync(from, amount, ct);
    await _accounts.CreditAsync(to, amount, ct);

    return new TransferResult(true, Guid.NewGuid().ToString());
